  {f : α → β},
  LipschitzWith.{u, v} K f →
    ∀ (s : Set.{u} α),
      LE.le.{0} (Metric.ediam.{v} (Set.image.{u, v} f s)) (HMul.hMul.{0, 0, 0} (↑K) (Metric.ediam.{u} s))

